// scripts/tests/unit/release-stage-run-artifact.test.ts — issue 1272's proof
// that the runner runs the whole list against a stage target it builds itself
// from a production dump at most 24 hours old: the journal (run.json) of one
// stage QA run, `bun run release:run --target stage --go <file>`, committed
// under scripts/tests/fixtures/release/ as stage-run-<runTs>.json. Stage has no
// preflight (owner, 2026-10-16): its QA run, every Q step, is the proof.
//
// The fixture is the artifact of one run, never regenerated by CI. When the
// step list changes, the hash here changes too, and a new stage QA run must
// be committed: that is the point.
import { describe, expect, test } from "bun:test";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import type { RunJournal } from "../../release/journal.ts";
import { loadReleaseRunbook } from "../../release/runbook.ts";
import { stepIds, stepListHash } from "../../release/steps.ts";

const dir = join(import.meta.dir, "..", "fixtures", "release");

describe("the committed stage QA run journal (issue 1272)", () => {
  const files = existsSync(dir) ? readdirSync(dir).filter((n) => /^stage-run-\d{8}T\d{6}Z\.json$/.test(n)).sort() : [];

  test("at least one stage QA run journal is committed (scripts/tests/fixtures/release/stage-run-<runTs>.json)", () => {
    expect(files.length, "no stage-run-<runTs>.json: commit the run.json of a stage QA run of this step list").toBeGreaterThan(0);
  });

  test.skipIf(files.length === 0)("the newest journal records the current step-list hash, a commit, and every step ok, skipped or accepted", () => {
    const run = JSON.parse(readFileSync(join(dir, files.at(-1)!), "utf8")) as RunJournal;
    expect(run.target).toBe("stage");
    expect(run.rmEnv).toBe("stage");
    // A stage run runs its release's own runbook: the template plus that release's version checks.
    const steps = loadReleaseRunbook(run.release).steps;
    expect(run.stepListHash).toBe(stepListHash(steps));
    expect(run.commit).toMatch(/^[0-9a-f]{40}$/);
    const ids = stepIds(steps);
    for (const id of ids) expect(["ok", "skipped", "accepted"], id).toContain(run.steps[id]?.status ?? "missing");
    // The QA steps ran: stage built its own target.
    for (const s of steps.filter((x) => x.phase === "qa")) expect(run.steps[s.id]?.status, s.id).toBe("ok");
    // Every Q step ran and passed, the release's version checks included: a change it ships is in place. Production's P and C steps were skipped.
    for (const s of steps.filter((x) => x.phase !== "qa")) expect(run.steps[s.id]?.status, s.id).toBe("skipped");
    // red control: a journal at another hash is not this proof.
    expect({ ...run, stepListHash: "0".repeat(64) }.stepListHash).not.toBe(stepListHash(steps));
  });
});
